public static final StateMachine<OrderStatus, OrderEvent, OrderContext> MACHINE =
        StateMachine.<OrderStatus, OrderEvent, OrderContext>builder("order")
                // O1 付款（级联自支付单）：服务类付款即出码
                .from(WAIT_PAY).on(PAY_CONFIRMED).by(SYSTEM)
                .toOneOf(Set.of(WAIT_FULFILL, FULFILLING), (f, c) -> c.serviceClass() ? FULFILLING : WAIT_FULFILL)
                .emit("OrderPaid").add()
                // O2 取消 / 关单（级联自支付单）
                .from(WAIT_PAY).on(CANCEL).by(SYSTEM).to(CANCELLED).add()
                // O3 开始备货：一次、不改状态；有进行中售后时不许点
                .from(WAIT_FULFILL).on(PREPARE).by(MERCHANT).when(AUTHORIZED, NOT_PREPARED, NO_OPEN_AFTER_SALE)
                .stay().emit("OrderPrepared").add()
                // O4 首张发货单揽收（级联自发货单）
                .from(WAIT_FULFILL).on(SHIPPED).by(SYSTEM).to(FULFILLING).emit("OrderShipped").add()
                // O5 自提到店
                .from(WAIT_FULFILL).on(ARRIVED_AT_PICKUP).by(MERCHANT).when(AUTHORIZED).to(FULFILLING)
                .emit("OrderArrived").add()
                // O6 核销：降级单只推进到履约中，由买家确认收口
                .from(WAIT_FULFILL, FULFILLING).on(VERIFIED).by(MERCHANT).when(AUTHORIZED)
                .toOneOf(Set.of(FULFILLING, COMPLETED), (f, c) -> c.requireBuyerConfirm() ? FULFILLING : COMPLETED)
                .emit("OrderVerified").add()
                // O7 商家标记送达：自送单可能已在「配送中」（FULFILLING），也可能直接从待发货送达
                .from(WAIT_FULFILL, FULFILLING).on(DELIVERED_BY_MERCHANT).by(MERCHANT).when(AUTHORIZED).to(COMPLETED)
                .emit("OrderCompleted").add()
                // O8 买家确认收货：也可从待履约出发 —— 微信购物订单的「确认收货」组件不等我们标发货
                .from(WAIT_FULFILL, FULFILLING).on(RECEIPT_CONFIRMED).by(BUYER).when(AUTHORIZED, ALL_SHIPPED).to(COMPLETED)
                .emit("OrderCompleted").add()
                // O9 自动确认收货（不是退款，保留自动）；有进行中售后不收口
                .from(FULFILLING).on(RECEIPT_AUTO_CONFIRMED).by(SYSTEM).when(AUTO_RECEIPT_DUE, NO_OPEN_AFTER_SALE)
                .to(COMPLETED).emit("OrderCompleted").add()
                // O10 全部行退完（级联自退款账本）
                .from(WAIT_FULFILL, FULFILLING, COMPLETED).on(FULLY_REFUNDED).by(SYSTEM).when(REFUND_COMPLETE)
                .to(REFUNDED).emit("OrderRefunded").add()
                // O11 人工干预：只能往前推，且不碰钱
                .from(WAIT_FULFILL, FULFILLING).on(INTERVENE).by(PLATFORM).when(AUTHORIZED, REMARK)
                .toOneOf(Set.of(FULFILLING, COMPLETED), OrderMachine::interveneTarget)
                .emit("OrderIntervened").add()
                .build()

public static final StateMachine<PaymentStatus, PaymentEvent, PaymentContext> MACHINE =
        StateMachine.<PaymentStatus, PaymentEvent, PaymentContext>builder("payment")
                // P1 下单：按支付方式落待付 / 待当面收
                .create().on(PLACE).by(BUYER, PLATFORM).when(AUTHORIZED)
                .toOneOf(Set.of(WAIT_PAY, WAIT_OFFLINE_PAY), (f, c) -> c.offlinePay() ? WAIT_OFFLINE_PAY : WAIT_PAY)
                .emit("PaymentPlaced").add()
                // P2 通道回调付款成功
                .from(WAIT_PAY).on(PAY_SUCCEEDED).by(CHANNEL).when(AMOUNT_MATCHES).to(PAID)
                .emit("PaymentPaid").add()
                // P3 商家确认当面收款
                .from(WAIT_OFFLINE_PAY).on(OFFLINE_CONFIRMED).by(MERCHANT).when(AUTHORIZED).to(PAID)
                .emit("PaymentPaid").add()
                // P4 买家 / 平台取消
                .from(WAIT_PAY, WAIT_OFFLINE_PAY).on(CANCEL).by(BUYER, PLATFORM).when(AUTHORIZED).to(CANCELLED)
                .emit("PaymentCancelled").add()
                // P5 超时关闭（与 P2 并发时由 CAS 决出一方）
                .from(WAIT_PAY).on(PAY_TIMEOUT).by(SYSTEM).when(DEADLINE_PASSED).to(CLOSED)
                .emit("PaymentClosed").add()
                // P6 关单后才到账：交易不成立，原路退回（售后 TRADE_VOID）
                .from(CLOSED, CANCELLED).on(LATE_PAY_SUCCEEDED).by(CHANNEL).stay()
                .emit("TradeVoidRefundRequired").add()
                .build()

public static final StateMachine<ShipmentStatus, ShipmentEvent, ShipmentContext> MACHINE =
        StateMachine.<ShipmentStatus, ShipmentEvent, ShipmentContext>builder("shipment")
                // H1 建发货单（录运单号）
                .create().on(CREATE).by(MERCHANT).when(AUTHORIZED, WAYBILL_VALID, WAYBILL_FREE).to(CREATED)
                .emit("ShipmentCreated").add()
                // H2 揽收（轨迹）
                .from(CREATED).on(PICKED_UP).by(CHANNEL).to(SHIPPED).emit("ShipmentPickedUp").add()
                // H3 承运商签收（轨迹）
                .from(SHIPPED).on(SIGNED).by(CHANNEL).to(DELIVERED).emit("ShipmentSigned").add()
                // H4 买家确认 / 自动确认收货
                .from(SHIPPED, DELIVERED).on(RECEIPT_CONFIRMED).by(BUYER, SYSTEM).to(RECEIVED)
                .emit("ShipmentReceived").add()
                // H5 改单号：旧单作废（新号先过与建单相同的守卫）
                .from(CREATED, SHIPPED).on(CORRECT_WAYBILL).by(MERCHANT).when(AUTHORIZED, WAYBILL_VALID, WAYBILL_FREE)
                .to(VOIDED).emit("ShipmentVoided").add()
                // H6 未揽收前取消
                .from(CREATED).on(CANCEL).by(MERCHANT).when(AUTHORIZED).to(VOIDED).emit("ShipmentVoided").add()
                .build()

